AttributeManager = {}
local this = {}

local PROP_DOUBLE = 10000.0

function AttributeManager.merge(allAttr, currAttr)
    for attrId, attrValue in pairs(currAttr) do
        local oldValue = allAttr[attrId] or 0
        local formula = string.tonumber(ConfigDataManager.getTableValue("cfg_att_info", "formula", "id", attrId))

        if formula == AttributeMergeType.ADD then
            local newValue = this.add(oldValue, attrValue)
            allAttr[attrId] = newValue
        elseif formula == AttributeMergeType.DEC_MUL_1 then
            local newValue = this.decThenMul1(oldValue, attrValue)
            allAttr[attrId] = newValue
        else
            local newValue = this.add(oldValue, attrValue)
            allAttr[attrId] = newValue
            error("改类型待补充")
        end
    end
end

--- 相加公式： oldVal + value
function this.add(oldVal, value)
    return oldVal + value
end

--- 减乘公式1： 被1减，后相乘, 后被1减
function this.decThenMul1(merged, unMerged)
    local ret = 1 - (1 - merged / PROP_DOUBLE) * (1 - unMerged / PROP_DOUBLE) ;
    ret = ret * PROP_DOUBLE;
    return this.round(ret);
end

function this.round(x)
    return math.floor(x + 0.5)
end